                continue
            for step in (-1, 1):
                rr = r + step
                while 0 <= rr < h:
                    # Existing horizontal bars form boundaries for a projection.
                    if any(grid[rr][x] != 0 for x in range(w) if x != c):
                        break
                    if out[rr][c] == 0:
